import React, { useState, useEffect, useCallback, useRef } from 'react'
import {
  Table,
  Row,
  Col,
  Spin,
  Typography,
  Input,
  Button,
  Icon,
  Alert,
  message
} from 'antd'
import { companyListColumns, FILTER_VALUES, TABLE_FIELDS } from './constants'
import { useCompanyList, useUpdateCompany } from '../../../state/CompanyList/hooks/useCompanyList'
import { useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import { useResetState } from '../../../state/hooks'
import PermissionCheckerV2 from '../../../../../../components/permissionCheckerV2'
import { ColTextAlignRight } from '../../../CommonComponents/index.style'
import { EbSectionWrapper } from '../../../CommonComponents'
import isEmpty from 'lodash/isEmpty'

const { Title } = Typography

const CompanyList = ({ history, ...props }) => {
  const [listData, setListData] = useState([])
  const [listMetaData, setListMetaData] = useState({})
  const [companyListData, request] = useCompanyList()
  const { updateCompanyRequest } = useUpdateCompany()
  const [{ COMPANY_LIST_LOADER, UPDATE_COMPANY_LOADER }] = useLoaderContextValue()
  const [{ COMPANY_LIST_ERROR, companyListStatus, UPDATE_COMPANY_ERROR, updateCompanyStatus }] = useErrorContextValue()
  const [searchText, setSearchText] = useState('')
  const [filteredInfo, setFilteredInfo] = useState({})
  const [sortedInfo, setSortedInfo] = useState({})
  const { resetState } = useResetState()
  const { resetError } = useResetError()
  const prevSearchText = useRef()

  const clearFiltersAndSorters = useCallback(() => {
    setFilteredInfo({})
    setSortedInfo({})
    const query = {}
    const searchString = String(searchText).toLowerCase()
    query.search_text = searchString
    request({ query })
  }, [setFilteredInfo, setSortedInfo, searchText, request])

  const handleToggleInternalExternal = useCallback((isInternal, companyId) => {
    updateCompanyRequest({
      company_id: companyId,
      is_internal: !isInternal
    })
  }, [updateCompanyRequest])

  useEffect(() => {
    if (updateCompanyStatus === 'success') {
      message.success('Company updated successfully')
      const query = {
        company_id: props.companyId,
        page: listMetaData.page,
        per_page: listMetaData.page_size
      }
      if (searchText) {
        const searchString = String(searchText).toLowerCase()
        query.search_text = searchString
      }
      request({ query })
      resetError(['updateCompanyStatus'])
    }
  }, [
    updateCompanyStatus,
    request,
    resetError,
    listMetaData,
    props.companyId,
    searchText
  ])

  useEffect(() => {
    return () => {
      resetState(['companyListData'])
      resetError(['COMPANY_LIST_ERROR'])
    }
  }, [resetState, resetError])

  useEffect(() => {
    if (companyListData) {
      if (companyListData.data) {
        setListData(companyListData.data)
        setListMetaData(companyListData.meta_data)
      }
    }
    return () => {
      // reset states here
      resetState(['companyDetailData', 'quotationPurposeData', 'companyPaymentsData', 'participantsInfoData', 'companyPackageData'])
    }
  }, [companyListData, resetError, resetState])

  const isInternalFilter = useCallback((filters = {}) => {
    const { is_internal: isInternalFilters } = filters
    if (Array.isArray(isInternalFilters) && isInternalFilters.length === 1) {
      const temp = { [TABLE_FIELDS.IS_INTERNAL]: isInternalFilters[0] === FILTER_VALUES[TABLE_FIELDS.IS_INTERNAL].INTERNAL ? 'True' : 'False' }
      return temp
    } else return {}
  }, [])

  const sortQueryParam = useCallback((sortedInfo) => {
    if (isEmpty(sortedInfo)) return {}
    return {
      sort_by: [sortedInfo.field],
      order: sortedInfo.order
    }
  }, [])

  useEffect(() => {
    if (prevSearchText.current === searchText) return
    const timeInterval = searchText ? 500 : 0
    const timer = setTimeout(() => {
      const query = {
        ...isInternalFilter(filteredInfo),
        ...sortQueryParam(sortedInfo)
      }
      if (searchText) {
        const searchString = String(searchText).toLowerCase()
        query.search_text = searchString
        request({ query })
      } else {
        request({ query })
      }
    }, timeInterval)
    prevSearchText.current = searchText
    return () => {
      clearTimeout(timer)
    }
  }, [searchText, request, filteredInfo, sortedInfo, isInternalFilter, sortQueryParam])

  const handleTableChange = useCallback((params, filters, sorter) => {
    setFilteredInfo(filters)
    setSortedInfo(sorter)
    const query = {
      page: params.current,
      per_page: params.pageSize,
      ...isInternalFilter(filters),
      ...sortQueryParam(sorter)
    }
    const searchString = String(searchText).toLowerCase()
    query.search_text = searchString
    request({ query })
  }, [searchText, isInternalFilter, request, sortQueryParam])

  const handleCompanyAddClick = useCallback(() => {
    history.push('/employee-benefits/add-company')
  }, [history])

  return (
    <EbSectionWrapper>
      <Row gutter={16}>
        <Col span={4}>
          <Title level={4}>Company List</Title>
        </Col>
        <Col span={8}>
          <Button onClick={clearFiltersAndSorters}>
            Clear filters and sorters
          </Button>
        </Col>
        <Col offset={2} span={6}>
          <Input
            placeholder='Search...'
            onChange={(e) => setSearchText(e.target.value)}
            allowClear
          />
        </Col>
        <ColTextAlignRight span={4}>
          <PermissionCheckerV2 requiredPermission='ops.eb_add_company'>
            <Button
              type='primary'
              onClick={handleCompanyAddClick}
            >
              Add Company
              <Icon type='plus' />
            </Button>
          </PermissionCheckerV2>
        </ColTextAlignRight>
      </Row>
      <Spin spinning={!!COMPANY_LIST_LOADER || !!UPDATE_COMPANY_LOADER}>
        {COMPANY_LIST_ERROR && <Alert type='error' message={companyListStatus} banner />}
        {UPDATE_COMPANY_ERROR && <Alert type='error' message={updateCompanyStatus} banner />}
        <Table
          columns={companyListColumns({ history, handleToggleInternalExternal, sortedInfo, filteredInfo })}
          dataSource={listData}
          onChange={handleTableChange}
          bordered
          rowKey={company => company.id}
          pagination={{
            pageSize: listMetaData.page_size,
            total: listMetaData.total_records,
            current: listMetaData.page
          }}
        />
      </Spin>
    </EbSectionWrapper>
  )
}

export default CompanyList
