import React from 'react'
import { format } from 'date-fns'
import { Icon, Switch } from 'antd'
import styled from 'styled-components'
import PermissionCheckerV2 from '../../../../../../components/permissionCheckerV2'

const SwitchStyleWrapper = styled.div`
  .border-radius-100 {
    border-radius: 100px;
  }
`

export const TABLE_FIELDS = {
  IS_INTERNAL: 'is_internal',
  NAME: 'name',
  CREATED_AT: 'created_at',
  SIZE: 'size'
}

export const FILTER_VALUES = {
  [TABLE_FIELDS.IS_INTERNAL]: {
    INTERNAL: 'internal',
    EXTERNAL: 'external'
  }
}

export const FILTER_OPTIONS = {
  [TABLE_FIELDS.IS_INTERNAL]: [
    { text: 'Test', value: FILTER_VALUES[TABLE_FIELDS.IS_INTERNAL].INTERNAL },
    { text: 'Real', value: FILTER_VALUES[TABLE_FIELDS.IS_INTERNAL].EXTERNAL }
  ]
}

export const companyListColumns = ({ history, handleToggleInternalExternal, filteredInfo, sortedInfo }) => ([
  {
    title: 'Action',
    width: 90,
    key: 1,
    render: (rowData) => (
      <PermissionCheckerV2 requiredPermission='ops.eb_view_company_info'>
        <Icon
          type='eye'
          twoToneColor='#0180c8'
          theme='twoTone'
          style={{ cursor: 'pointer' }}
          onClick={() => history.push(`/employee-benefits/company-list/${rowData.id}`)}
        />
      </PermissionCheckerV2>
    )
  },
  {
    title: 'Company Name',
    dataIndex: 'name',
    key: 2,
    sorter: () => {},
    sortOrder: sortedInfo.columnKey === 2 && sortedInfo.order,
    width: 220
  },
  {
    title: 'Company Industry',
    dataIndex: 'industry',
    key: 3
  },
  {
    title: 'Company Size',
    dataIndex: 'size',
    key: 4,
    sorter: () => {},
    sortOrder: sortedInfo.columnKey === 4 && sortedInfo.order
  },
  {
    title: 'Created At',
    dataIndex: 'created_at',
    render: date => format(date, 'DD MMMM YYYY'),
    key: 5,
    sorter: () => {},
    sortOrder: sortedInfo.columnKey === 5 && sortedInfo.order,
    width: 180
  },
  {
    title: 'Company Type',
    dataIndex: 'is_internal',
    render: (isInternal, rowData) => (
      <PermissionCheckerV2 requiredPermission='ops.eb_add_company'>
        <SwitchStyleWrapper>
          <Switch
            unCheckedChildren='Test'
            checkedChildren='Real'
            checked={!isInternal}
            size='default'
            className='border-radius-100'
            onChange={(isInternalUpdatedValue) => handleToggleInternalExternal(isInternalUpdatedValue, rowData.id)}
          />
        </SwitchStyleWrapper>
      </PermissionCheckerV2>
    ),
    filters: FILTER_OPTIONS[TABLE_FIELDS.IS_INTERNAL],
    filteredValue: filteredInfo.is_internal || null,
    ellipsis: true
  }
])
