import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useCallback } from 'react'
import { useEBContextValue } from '../../../context/index'
import actions from '../actions'

export const useCompanyList = () => {
  const [{ companyListData }, dispatch] = useEBContextValue()
  //  follow this
  const [callApi] = useServiceRequest(dispatch)
  const request = useCallback((payload = {}) => {
    callApi(actions.geCompanyList(payload))
  }, [callApi])
  return [companyListData, request]
}

export const useUpdateCompany = () => {
  const [{ updateCompanyStatus }, dispatch] = useEBContextValue()
  const [callApi] = useServiceRequest(dispatch)
  const updateCompanyRequest = useCallback(payload => {
    callApi(actions.updateCompany({ body: payload }))
  }, [callApi])
  return { updateCompanyStatus, updateCompanyRequest }
}
