import { mapArrayElementsKeysToObjectKeys } from '../../../../../helpers/utility'
import actions from './actions'

export const COMPANY_NAME = 'companyName'

const INITIAL_STATE = {
}

const ebReducer = (state, action) => {
  const { payload } = action
  switch (action.type) {
    case actions.RESET_EB_STATE:
      return { ...state, ...mapArrayElementsKeysToObjectKeys(payload) }
    case actions.COMPANY_LIST:
    case actions.FILE_UPLOADS_LIST:
    case actions.COMPANY_DETAIL:
    case actions.QUOTATION_PURPOSE:
    case actions.COMPANY_PAYMENTS:
    case actions.COMPANY_PACKAGE:
    case actions.CREATE_PAYMENT:
    case actions.HEALTH_CARD_STATUS_LIST:
    case actions.UPDATE_PAYMENT_STATUS:
    case actions.PARTICIPANTS_INFO:
    case actions.PAID_PARTICIPANT_LIST:
    case actions.UNPAID_PARTICIPANT_LIST:
    case actions.PENDING_PARTICIPANT_LIST:
    case actions.PROVIDERS_LIST:
    case actions.PACKAGE_DETAIL:
    case actions.ADD_PACKAGE:
    case actions.UPLOAD_PACKAGE_PDF:
    case actions.UPDATE_PACKAGE_PREMIUM:
    case actions.PACKAGE_ADD_BENEFITS:
    case actions.FILE_UPLOAD:
    case actions.GCS_UPLOAD:
    case actions.EMPLOYEE_DATA_UPLOAD:
    case actions.FILE_DOWNLOAD:
    case actions.ACCEPT_PAYMENT:
    case actions.CANCEL_PAYMENT:
    case actions.DOWNLOAD_PARTICIPANT:
    case actions.BENEFITS:
    case actions.ADD_EMPLOYEE:
    case actions.COMPANY_FORM_PARAMETERS:
    case actions.BUSINESS_TYPES:
    case actions.CREATE_COMPANY:
    case actions.DOWNLOAD_FILE_UPLOADS:
    case actions.FILE_DETAIL:
    case actions.CANCEL_FILE:
    case actions.FILE_ROWS:
    case actions.EMPLOYEE_DETAIL:
    case actions.EMPLOYEE_LIST:
    case actions.DEACTIVATE_PARTICIPANTS:
    case actions.UPDATE_EMPLOYEE:
    case actions.DEACTIVATE_DEPENDENTS:
    case actions.ADD_DEPENDENTS:
    case actions.UPDATE_DEPENDENTS:
    case actions.UPLOAD_PACKAGE_FILE:
      return { ...state, ...payload }
    default:
      return state
  }
}

export { INITIAL_STATE }
export default ebReducer
