import ebUrls from '../../../../../request/urls/employeeBenefit'

const actions = {
  COMPANY_LIST_REQUEST: 'COMPANY_LIST_REQUEST',
  COMPANY_LIST: 'COMPANY_LIST',
  UPDATE_COMPANY_REQUEST: 'UPDATE_COMPANY_REQUEST',
  UPDATE_COMPANY: 'UPDATE_COMPANY',

  geCompanyList: (payload) => ({
    type: actions.COMPANY_LIST_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: ebUrls.companyList
    }
  }),
  updateCompany: payload => ({
    type: actions.UPDATE_COMPANY_REQUEST,
    payload: {
      ...payload,
      method: 'post',
      url: ebUrls.updateCompany
    }
  })
}

export default actions
